export function sectionTimeWarpMarkup(section){const keys=section.timeWarp;let html='<details class="section-time-warp" open><summary>시간 리매핑</summary><label>사용<input type="checkbox" data-section-warp="'+section.id+'" '+(keys?'checked':'')+'></label>';if(keys){const maxX=Math.max(1,keys.at(-1).time),maxY=Math.max(1,keys.at(-1).value),points=keys.map(k=>(5+90*k.time/maxX)+','+(95-90*k.value/maxY)).join(' ');html+='<svg preserveAspectRatio="none" viewBox="0 0 100 100" height="90" width="100%" aria-label="시간 리매핑 곡선"><path d="M5 5V95H95" fill="none" stroke="currentColor" opacity=".3"/><polyline points="'+points+'" fill="none" stroke="#67a8e4" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="section-warp-keys">';for(const[k,key]of keys.entries())html+='<div class="gameplay-vector"><label>구간 시간<input type="number" step=".01" data-warp-section="'+section.id+'" data-warp-index="'+k+'" data-warp-field="time" value="'+key.time+'" '+(!k?'disabled data-warp-locked':'')+'></label><label>원본 시간<input type="number" step=".01" data-warp-section="'+section.id+'" data-warp-index="'+k+'" data-warp-field="value" value="'+key.value+'" '+(!k?'disabled data-warp-locked':'')+'></label><button data-warp-remove="'+section.id+'" data-warp-index="'+k+'" '+(!k||keys.length<=2?'disabled data-warp-locked':'')+' aria-label="시간 키 삭제">×</button></div>';html+='</div><button data-warp-add="'+section.id+'" '+(keys.length>=256?'disabled data-warp-locked':'')+'>시간 키 추가</button>';}return html+'</details>';}
